  2→package com.jonnyzzz.mcpSteroid.proxy
  3→
  4→import kotlinx.coroutines.CoroutineScope
  5→import kotlinx.coroutines.Dispatchers
  6→import kotlinx.coroutines.SupervisorJob
  7→import kotlinx.coroutines.delay
  8→import kotlinx.coroutines.isActive
  9→import kotlinx.coroutines.launch
 10→import kotlinx.coroutines.runBlocking
 11→
 12→fun main(args: Array<String>) {
 13→    val cliArgs = parseArgs(args.toList())
 14→
 15→    if (cliArgs.help) {
 16→        System.err.print(
 17→            """
 18→            Usage: mcp-steroid-proxy [--config path] [--scan-interval ms] [--log-traffic] [--cli]
 19→
 20→            Default mode:
 21→              stdio MCP server over stdin/stdout
 22→
 23→            CLI mode:
 24→              --cli [--cli-method <method> --cli-params-json '<json>']
 25→              --cli --tool <toolName> [--arguments-json '<json>']
 26→              --cli --uri <resourceUri>
 27→
 28→            CLI defaults to --cli-method tools/list when no CLI selector is provided.
 29→            """.trimIndent() + "\n"
 30→        )
 31→        return
 32→    }
 33→
 34→    val config = loadConfig(cliArgs).also { it.version = loadProxyVersion() }
 35→    val traffic = TrafficLogger(config)
 36→    val registry = ServerRegistry(config, traffic)
 37→    val beacon = NpxBeacon(config)
 38→
 39→    runBlocking {
 40→        val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
 41→
 42→        beacon.capture(BeaconEvents.STARTED, mapOf("mode" to cliArgs.mode))
 43→
 44→        registry.refreshDiscovery()
 45→        beacon.captureDiscoveryChanged(registry, "startup")
 46→
 47→        if (cliArgs.mode == "cli") {
 48→            try {
 49→                emitUpgradeNotice(registry, config, beacon)
 50→            } catch (e: Exception) {
 51→                // Ignore update-check failures in CLI mode
 52→            }
 53→            runCliMode(cliArgs, registry, traffic, beacon)
 54→            beacon.shutdown()
 55→            return@runBlocking
 56→        }
 57→
 58→        // Schedule update checks
 59→        if (config.updates.enabled) {
 60→            scope.launch {
 61→                delay(config.updates.initialDelayMs)
 62→                runUpgradeCheck(registry, config, beacon)
 63→                while (isActive) {
 64→                    delay(config.updates.intervalMs)
 65→                    runUpgradeCheck(registry, config, beacon)
 66→                }
 67→            }
 68→        }
 69→
 70→        // Periodic discovery refresh
 71→        scope.launch {
 72→            while (isActive) {
 73→                delay(config.scanIntervalMs)
 74→                try {
 75→                    registry.refreshDiscovery()
 76→                    beacon.captureDiscoveryChanged(registry, "interval")
 77→                } catch (e: Exception) {
 78→                    // Ignore refresh failures
 79→                }
 80→            }
 81→        }
 82→
 83→        beacon.startHeartbeat(scope, registry)
 84→
 85→        // Run stdio server (blocks until stdin closes)
 86→        val server = StdioServer(registry, traffic, beacon)
 87→        server.run()
 88→
 89→        beacon.shutdown()
 90→    }
 91→}
 92→
 93→private var upgradeNoticeShown = false
 94→private var upgradeCheckInFlight = false
 95→
 96→private suspend fun emitUpgradeNotice(registry: ServerRegistry, config: ProxyConfig, beacon: NpxBeacon) {
 97→    if (upgradeCheckInFlight) return
 98→    upgradeCheckInFlight = true
 99→    try {
100→        val notice = buildUpgradeNotice(registry, config)
101→        if (notice != null && !upgradeNoticeShown) {
102→            upgradeNoticeShown = true
103→            System.err.write("$notice\n".toByteArray(Charsets.UTF_8))
104→            System.err.flush()
105→            beacon.capture(BeaconEvents.UPGRADE_RECOMMENDED, mapOf(
106→                "current_version" to extractBaseVersion(config.version ?: "")
107→            ))
108→        }
109→    } finally {
110→        upgradeCheckInFlight = false
111→    }
112→}
113→
114→private suspend fun runUpgradeCheck(registry: ServerRegistry, config: ProxyConfig, beacon: NpxBeacon) {
115→    try {
116→        emitUpgradeNotice(registry, config, beacon)
117→    } catch (e: Exception) {
118→        // Ignore periodic update-check failures
119→    }
120→}
