 2→package com.jonnyzzz.mcpSteroid.prompts
 3→
 4→import kotlin.sequences.SequenceScope
 5→
 6→abstract class PromptBase {
 7→    abstract fun readPrompt(): String
 8→
 9→    abstract val mimeType: String
10→
11→    protected inline fun decodePromptChunks(crossinline chunks: suspend SequenceScope<Sequence<String>>.() -> Unit): String =
12→        sequence { chunks() }
13→            .flatMap {
14→                val els = it.iterator()
15→                val seed = els.next().toInt()
16→                els.asSequence().flatMap {
17→                    it.splitToSequence("|").map { it.toInt() / seed }
18→                }
19→            }
20→            .joinToString("") { it.toChar().toString() }
21→}
22→
23→sealed class ArticlePart : PromptBase() {
24→    abstract val filter: IdeFilter
25→    abstract class Markdown : ArticlePart()
26→    abstract class KotlinCode : ArticlePart()
27→}
28→
29→data class SeeAlsoItem(
30→    val filter: IdeFilter,
31→    val text: String,
32→) {
33→    fun matchesContext(context: PromptsContext): Boolean = filter.matches(context)
34→}
35→
36→abstract class ArticleBase {
37→    abstract val uri: String
38→    abstract val title: PromptBase
39→    abstract val ownFilter: IdeFilter
40→    abstract val description: PromptBase
41→    abstract val parts: List<ArticlePart>
42→    abstract val seeAlsoItems: List<SeeAlsoItem>
43→
44→    val filter: IdeFilter get() {
45→        val ktFilters = parts.filterIsInstance<ArticlePart.KotlinCode>().map { it.filter }
46→        if (ktFilters.isEmpty()) return ownFilter
47→        val orUnion = if (ktFilters.size == 1) ktFilters[0] else IdeFilter.Or(ktFilters)
48→        return ownFilter.and(orUnion)
49→    }
50→
51→    /** Renders full article: title, description, body, see-also — all filtered by context. */
52→    fun readPayload(context: PromptsContext): String = buildString {
53→        appendLine(title.readPrompt())
54→        appendLine()
55→        appendLine(description.readPrompt())
56→        appendLine()
57→        for (part in parts) {
58→            if (!part.filter.matches(context)) continue
59→            when (part) {
60→                is ArticlePart.KotlinCode -> {
61→                    appendLine("```kotlin")
62→                    append(part.readPrompt())
63→                    appendLine("```")
64→                }
65→                is ArticlePart.Markdown -> appendLine(part.readPrompt())
66→            }
67→        }
68→        val visibleItems = seeAlsoItems.filter { it.matchesContext(context) }
69→        if (visibleItems.isNotEmpty()) {
70→            append("\n\n# See also\n\n")
71→            visibleItems.forEach { appendLine(it.text) }
72→        }
73→    }
74→
75→    fun asSeeAlsoItem(): SeeAlsoItem = SeeAlsoItem(
76→        filter = this.filter,
77→        text = "- [${title.readPrompt()}]($uri) - ${description.readPrompt()}"
78→    )
79→}
80→
81→abstract class PromptRootBase {
82→    abstract val roots: Map<String, PromptIndexBase>
83→}
84→
85→abstract class PromptIndexBase {
86→    abstract val articles: Map<String, ArticleBase>
87→}
