470→        val home = File(System.getProperty("user.home"))
471→        val endpoints = home.listFiles { f -> f.name.matches(Regex("\\.\\d+\\.hot-reload")) }
472→            ?.mapNotNull { f ->
473→                val pid = Regex("\\.(\\d+)\\.").find(f.name)?.groupValues?.get(1)?.toLongOrNull() ?: return@mapNotNull null
474→                if (!ProcessHandle.of(pid).isPresent) return@mapNotNull null
475→                val lines = f.readLines().takeIf { it.size >= 2 } ?: return@mapNotNull null
476→                lines[0] to lines[1]
477→            }?.distinctBy { it.first } ?: emptyList()
478→
479→        if (endpoints.isEmpty()) { println("No running IDEs found"); return@doLast }
480→
481→        endpoints.forEach { (url, token) ->
482→            println("\n→ $url")
483→            val conn = (URI(url).toURL().openConnection() as HttpURLConnection).apply {
484→                requestMethod = "POST"; doOutput = true
485→                setRequestProperty("Authorization", token)
486→                setRequestProperty("Content-Type", "application/octet-stream")
487→                connectTimeout = 5000; readTimeout = 300000
488→            }
489→            conn.outputStream.use { out -> zip.inputStream().use { it.copyTo(out) } }
490→            if (conn.responseCode in 200..299) {
491→                conn.inputStream.bufferedReader().forEachLine { println("  $it") }
492→            } else {
493→                println("  ✗ HTTP ${conn.responseCode}")
494→            }
495→        }
496→    }
