  4→import com.intellij.openapi.diagnostic.thisLogger
  5→import kotlinx.serialization.json.*
  6→
  7→/**
  8→ * Core MCP server logic that handles JSON-RPC message dispatch.
  9→ * Independent of transport layer.
 10→ */
 11→class McpServerCore(
 12→    val serverInfo: ServerInfo,
 13→    private val capabilities: ServerCapabilities,
 14→    private val instructions: String? = null,
 15→) {
 16→    private val log = thisLogger()
 17→    val sessionManager = McpSessionManager()
 18→    val toolRegistry = McpToolRegistry()
 19→    val resourceRegistry = McpResourceRegistry()
 20→    val promptRegistry = McpPromptRegistry()
 21→
 22→    /**
 23→     * Handle an incoming JSON-RPC message and return a response (if applicable).
 24→     * Returns null for notifications that don't require a response.
 25→     */
 26→    suspend fun handleMessage(message: String, session: McpSession): String? {
 27→        val jsonElement = try {
 28→            McpJson.parseToJsonElement(message)
 29→        } catch (e: Exception) {
 30→            return encodeError(JsonNull, JsonRpcErrorCodes.PARSE_ERROR, "Parse error: ${e.message}")
 31→        }
 32→
 33→        return when (jsonElement) {
 34→            is JsonArray -> handleBatch(jsonElement, session)
 35→            is JsonObject -> handleSingle(jsonElement, session)
 36→            else -> encodeError(JsonNull, JsonRpcErrorCodes.INVALID_REQUEST, "Invalid request")
 37→        }
 38→    }
 39→
 40→    private suspend fun handleBatch(batch: JsonArray, session: McpSession): String {
 41→        val responses = batch.mapNotNull { element ->
 42→            if (element is JsonObject) {
 43→                handleSingle(element, session)?.let { McpJson.parseToJsonElement(it) }
 44→            } else {
 45→                McpJson.parseToJsonElement(
 46→                    encodeError(JsonNull, JsonRpcErrorCodes.INVALID_REQUEST, "Invalid request in batch")
 47→                )
 48→            }
 49→        }
 50→        return McpJson.encodeToString(JsonArray.serializer(), JsonArray(responses))
 51→    }
 52→
 53→    private suspend fun handleSingle(json: JsonObject, session: McpSession): String? {
 54→        val id = json["id"]
 55→        val method = json["method"]?.jsonPrimitive?.contentOrNull
 56→
 57→        // Check if this is a notification (no id)
 58→        if (id == null) {
 59→            if (method != null) {
 60→                handleNotification(method)
 61→            }
 62→            return null
 63→        }
 64→
 65→        // Check if this is a response to a server-initiated request (has id but no method)
 66→        if (method == null) {
 67→            // This might be a response to a server request (like sampling)
 68→            val idString = id.toString().trim('"')
 69→            val result = json["result"]
 70→            val error = json["error"]
 71→
 72→            if (result != null) {
 73→                if (session.handleResponse(idString, result)) {
 74→                    // Successfully routed the response, no need to reply
 75→                    return null
 76→                }
 77→            } else if (error != null) {
 78→                val rpcError = try {
 79→                    McpJson.decodeFromJsonElement<JsonRpcError>(error)
 80→                } catch (_: Exception) {
 81→                    JsonRpcError(code = -1, message = "Unknown error")
 82→                }
 83→                if (session.handleErrorResponse(idString, rpcError)) {
 84→                    return null
 85→                }
 86→            }
 87→
 88→            return encodeError(id, JsonRpcErrorCodes.INVALID_REQUEST, "Missing method")
 89→        }
 90→
 91→        return handleRequest(id, method, json["params"]?.jsonObject, session)
 92→    }
 93→
 94→    private suspend fun handleRequest(
 95→        id: JsonElement,
 96→        method: String,
 97→        params: JsonObject?,
 98→        session: McpSession
 99→    ): String {
100→        return when (method) {
101→            McpMethods.INITIALIZE -> handleInitialize(id, params, session)
102→            McpMethods.PING -> handlePing(id)
103→            McpMethods.TOOLS_LIST -> handleToolsList(id)
104→            McpMethods.TOOLS_CALL -> handleToolsCall(id, params, session)
105→            McpMethods.PROMPTS_LIST -> handlePromptsList(id, params)
106→            McpMethods.PROMPTS_GET -> handlePromptsGet(id, params)
107→            McpMethods.RESOURCES_LIST -> handleResourcesList(id)
108→            McpMethods.RESOURCES_READ -> handleResourcesRead(id, params)
109→            else -> encodeError(id, JsonRpcErrorCodes.METHOD_NOT_FOUND, "Method not found: $method")
110→        }
111→    }
112→
113→    private fun handleNotification(method: String) {
114→        log.info("Client notification: $method")
115→        when (method) {
116→            McpMethods.INITIALIZED -> {
117→                // Client confirmed initialization - nothing special needed
118→            }
119→            // Handle other notifications as needed
120→        }
121→    }
122→
123→    private fun handleInitialize(id: JsonElement, params: JsonObject?, session: McpSession): String {
124→        val initParams = try {
125→            params?.let { McpJson.decodeFromJsonElement<InitializeParams>(it) }
126→        } catch (e: Exception) {
127→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Invalid initialize params: ${e.message}")
128→        }
129→
130→        if (initParams != null) {
131→            session.markInitialized(initParams.clientInfo, initParams.capabilities)
132→        }
133→
134→        val result = InitializeResult(
135→            protocolVersion = MCP_PROTOCOL_VERSION,
136→            capabilities = capabilities,
137→            serverInfo = serverInfo,
138→            instructions = instructions
139→        )
140→
141→        return encodeResult(id, McpJson.encodeToJsonElement(result))
142→    }
143→
144→    private fun handlePing(id: JsonElement): String {
145→        return encodeResult(id, JsonObject(emptyMap()))
146→    }
147→
148→    private fun handleToolsList(id: JsonElement): String {
149→        val tools = toolRegistry.listTools()
150→        val result = ToolsListResult(tools = tools)
151→        return encodeResult(id, McpJson.encodeToJsonElement(result))
152→    }
153→
154→    private suspend fun handleToolsCall(id: JsonElement, params: JsonObject?, session: McpSession): String {
155→        if (params == null) {
156→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Missing tool call params")
157→        }
158→
159→        val callParams = try {
160→            McpJson
161→                .decodeFromJsonElement<ToolCallParams>(params)
162→                .copy(rawArguments = params)
163→        } catch (e: Exception) {
164→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Invalid tool call params: ${e.message}")
165→        }
166→
167→        val result = toolRegistry.callTool(callParams, session)
168→        return encodeResult(id, McpJson.encodeToJsonElement(result))
169→    }
170→
171→    private fun handleResourcesList(id: JsonElement): String {
172→        val resources = resourceRegistry.listResources()
173→        val result = ResourcesListResult(resources = resources)
174→        return encodeResult(id, McpJson.encodeToJsonElement(result))
175→    }
176→
177→    private fun handlePromptsList(id: JsonElement, params: JsonObject?): String {
178→        if (params != null) {
179→            try {
180→                McpJson.decodeFromJsonElement<PromptsListParams>(params)
181→            } catch (e: Exception) {
182→                return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Invalid prompts list params: ${e.message}")
183→            }
184→        }
185→        val prompts = promptRegistry.listPrompts()
186→        val result = PromptsListResult(prompts = prompts)
187→        return encodeResult(id, McpJson.encodeToJsonElement(result))
188→    }
189→
190→    private fun handlePromptsGet(id: JsonElement, params: JsonObject?): String {
191→        if (params == null) {
192→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Missing prompt get params")
193→        }
194→
195→        val getParams = try {
196→            McpJson.decodeFromJsonElement<PromptGetParams>(params)
197→        } catch (e: Exception) {
198→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Invalid prompt get params: ${e.message}")
199→        }
200→
201→        val result = promptRegistry.getPrompt(getParams)
202→            ?: return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Prompt not found: ${getParams.name}")
203→
204→        return encodeResult(id, McpJson.encodeToJsonElement(result))
205→    }
206→
207→    private fun handleResourcesRead(id: JsonElement, params: JsonObject?): String {
208→        if (params == null) {
209→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Missing resource read params")
210→        }
211→
212→        val readParams = try {
213→            McpJson.decodeFromJsonElement<ResourceReadParams>(params)
214→        } catch (e: Exception) {
215→            return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Invalid resource read params: ${e.message}")
216→        }
217→
218→        val result = resourceRegistry.readResource(readParams.uri)
219→            ?: return encodeError(id, JsonRpcErrorCodes.INVALID_PARAMS, "Resource not found: ${readParams.uri}")
220→
221→        return encodeResult(id, McpJson.encodeToJsonElement(result))
222→    }
223→
