  2→package com.jonnyzzz.mcpSteroid.proxy
  3→
  4→import kotlinx.coroutines.Dispatchers
  5→import kotlinx.coroutines.channels.Channel
  6→import kotlinx.coroutines.launch
  7→import kotlinx.serialization.json.Json
  8→import kotlinx.serialization.json.JsonArray
  9→import kotlinx.serialization.json.JsonObject
 10→import kotlinx.serialization.json.buildJsonObject
 11→import kotlinx.serialization.json.contentOrNull
 12→import kotlinx.serialization.json.jsonPrimitive
 13→import kotlinx.serialization.json.put
 14→import java.io.InputStream
 15→import java.io.OutputStream
 16→
 17→private val prettyJson = Json { prettyPrint = true }
 18→
 19→class StdioServer(
 20→    private val registry: ServerRegistry,
 21→    private val traffic: TrafficLogger,
 22→    private val beacon: NpxBeacon?,
 23→    private val inputStream: InputStream = System.`in`,
 24→    private val outputStream: OutputStream = System.out
 25→) {
 26→    private val json = Json { ignoreUnknownKeys = true }
 27→    private var outputMode: String? = null  // "framed" | "ndjson"
 28→
 29→    private fun writeResponse(payload: JsonObject) {
 30→        val text = Json.encodeToString(JsonObject.serializer(), payload)
 31→        val message = when (outputMode) {
 32→            "ndjson" -> encodeNdjsonMessage(text)
 33→            else -> encodeFramedMessage(text)
 34→        }
 35→        synchronized(outputStream) {
 36→            outputStream.write(message.toByteArray(Charsets.UTF_8))
 37→            outputStream.flush()
 38→        }
 39→    }
 40→
 41→    private suspend fun handleSingle(request: JsonObject): JsonObject? {
 42→        val idElement = request["id"]
 43→        val method = request["method"]?.jsonPrimitive?.contentOrNull
 44→
 45→        // Notification — no id, no response
 46→        if (idElement == null || idElement is kotlinx.serialization.json.JsonNull) {
 47→            return null
 48→        }
 49→
 50→        val id = idElement.jsonPrimitive.contentOrNull ?: return null
 51→
 52→        if (method == null) {
 53→            return jsonRpcError(id, -32600, "Missing method")
 54→        }
 55→
 56→        return try {
 57→            val params = request["params"] as? JsonObject ?: JsonObject(emptyMap())
 58→            val result = handleRpc(
 59→                method = method,
 60→                params = params,
 61→                registry = registry,
 62→                beacon = beacon,
 63→                notify = { notifyMethod, notifyParams ->
 64→                    writeResponse(buildJsonObject {
 65→                        put("jsonrpc", JSONRPC_VERSION)
 66→                        put("method", notifyMethod)
 67→                        put("params", notifyParams)
 68→                    })
 69→                }
 70→            )
 71→            jsonRpcResult(id, result)
 72→        } catch (e: RpcException) {
 73→            jsonRpcError(id, e.code, e.message ?: "RPC error")
 74→        } catch (e: Exception) {
 75→            jsonRpcError(id, -32603, e.message ?: "Internal error")
 76→        }
 77→    }
 78→
 79→    private suspend fun handlePayload(payload: Any?) {
 80→        if (payload == null) {
 81→            writeResponse(jsonRpcError(null, -32600, "Empty request body"))
 82→            return
 83→        }
 84→
 85→        if (payload is JsonArray) {
 86→            val responses = mutableListOf<JsonObject>()
 87→            for (item in payload) {
 88→                val obj = item as? JsonObject
 89→                    ?: continue
 90→                val response = handleSingle(obj)
 91→                if (response != null) responses += response
 92→            }
 93→            if (responses.isNotEmpty()) {
 94→                // Batch response: write as JSON array
 95→                val text = Json.encodeToString(JsonArray.serializer(), JsonArray(responses))
 96→                val message = when (outputMode) {
 97→                    "ndjson" -> encodeNdjsonMessage(text)
 98→                    else -> encodeFramedMessage(text)
 99→                }
100→                synchronized(outputStream) {
101→                    outputStream.write(message.toByteArray(Charsets.UTF_8))
102→                    outputStream.flush()
103→                }
104→            }
105→            return
106→        }
107→
108→        if (payload !is JsonObject) {
109→            writeResponse(jsonRpcError(null, -32600, "Invalid request"))
110→            return
111→        }
112→
113→        traffic.log(TrafficRecord(
114→            ts = nowIso(),
115→            direction = "proxy-in",
116→            payload = payload
117→        ))
118→
119→        val response = handleSingle(payload)
120→        if (response != null) {
121→            traffic.log(TrafficRecord(
122→                ts = nowIso(),
123→                direction = "proxy-out",
124→                payload = response
125→            ))
126→            writeResponse(response)
127→        }
128→    }
129→
130→    suspend fun run() {
131→        val frameChannel = Channel<FrameResult>(Channel.UNLIMITED)
132→        val buffer = FramingBuffer()
133→
134→        // Stdin reader — blocks on Dispatchers.IO
135→        val readerJob = kotlinx.coroutines.coroutineScope {
136→            launch(Dispatchers.IO) {
137→                val buf = ByteArray(8192)
138→                try {
139→                    while (true) {
140→                        val n = inputStream.read(buf)
141→                        if (n < 0) break  // EOF
142→                        buffer.append(buf, n)
143→                        while (true) {
144→                            val frame = buffer.readNextFrame() ?: break
145→                            if (outputMode == null) outputMode = frame.mode
146→                            frameChannel.send(frame)
147→                        }
148→                    }
149→                } finally {
150→                    frameChannel.close()
151→                }
152→            }
153→        }
154→
155→        // Sequential frame processor
156→        for (frame in frameChannel) {
157→            if (frame.payloadText.isBlank()) continue
158→
159→            val parsed = try {
160→                json.parseToJsonElement(frame.payloadText)
161→            } catch (e: Exception) {
162→                writeResponse(jsonRpcError(null, -32700, "Parse error: ${e.message}"))
163→                continue
164→            }
165→
166→            try {
167→                handlePayload(parsed)
168→            } catch (e: Exception) {
169→                writeResponse(jsonRpcError(null, -32603, e.message ?: "Internal error"))
170→            }
171→        }
172→    }
173→}
174→
175→suspend fun runCliMode(args: CliArgs, registry: ServerRegistry, traffic: TrafficLogger, beacon: NpxBeacon?) {
176→    val (method, params) = buildCliRequest(args)
177→
178→    traffic.log(TrafficRecord(
179→        ts = nowIso(),
180→        direction = "cli-in",
181→        payload = params
182→    ))
183→
184→    val result = handleRpc(method, params, registry, beacon)
185→
186→    traffic.log(TrafficRecord(
187→        ts = nowIso(),
188→        direction = "cli-out",
189→        payload = result
190→    ))
191→
192→    val text = prettyJson.encodeToString(JsonObject.serializer(), result)
193→    System.out.write("$text\n".toByteArray(Charsets.UTF_8))
194→    System.out.flush()
195→}
196→

