        }
    )

    /** All tool definitions in registration order */
    val ALL: List<ToolDef> = listOf(
        LIST_PROJECTS,
        LIST_WINDOWS,
        EXECUTE_CODE,
        ACTION_DISCOVERY,
        VISION_SCREENSHOT,
        VISION_INPUT,
        OPEN_PROJECT,
